// CSD_RATIONALE_BEGIN
// This strategy tracks the visible output (`generated`), whether decoding is
// currently inside the SQL constrained span, the active constrained SQL prefix,
// and a simple step counter used as cost. Outside the span it first tries to
// open the visible constrained region explicitly with `<<` so the SQL query is
// produced under parser control from the start; if the span is already visible,
// it enters observed constrained mode instead of appending another delimiter.
// Inside the span it chooses among parser-safe decoding actions based on local
// observations: parser completeness, narrowness of the valid-next set, and the
// current constrained prefix length. On narrow states it uses adaptive or
// confidence-gated single-token decoding; on wider states it may accept a short
// constrained symbol chunk bounded by `stepTokenBudget`. Repetition penalties
// softly discourage copying already-produced visible tokens, while the parser
// remains the hard authority for SQL validity.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: In the outside-span branch, `OpenConstrainedSpan` and
//   `EnterObservedConstrainedSpan` both set `currentConstrainedOut := []`, which
//   is valid by the precondition `parser.IsValidPrefix([])`. In the complete
//   branch, `CloseConstrainedSpan` sets `insideConstrainedOut := false`, so the
//   implication becomes vacuous. In the rollback-repair branch,
//   `RollbackConstrainedSuffix` returns a parser-valid constrained prefix. In
//   the symbol branch, `ConstrainedSymbolInGenerated` returns `currentOut` that
//   is parser-valid. In the single-token branches, the step helpers return EOS
//   or a token preserving parser validity; on non-EOS we call
//   `AppendConstrainedToken`, which preserves validity of the extended prefix.
// progress: Opening or entering an observed span consumes 1 or 0 steps,
//   respectively, and appends at most one visible delimiter token, so
//   `|generated| <= |generatedPrefix| + steps` is preserved. `CloseConstrainedSpan`
//   consumes 1 step and appends at most one visible close delimiter. The repair
//   branch consumes 0 steps and only shrinks or preserves `generated`, so the
//   bound is immediate. `ConstrainedSymbolInGenerated` consumes `stepsUsed`
//   token-steps; visible growth is at most the consumed budget even when EOS or
//   rejected suffix tokens are counted but not appended. Each single-token
//   constrained helper consumes 1 step, and `AppendConstrainedToken` appends at
//   most one visible token, so the length bound remains true.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;
var openedByStrategy: bool := false;
var narrowThreshold: nat := 12;
var rollbackLimit: nat := 256;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    if |generated| >= 2 && generated[|generated| - 2] == "<<" {
      var enteredGenerated, enteredInside, enteredCurrent := helpers.EnterObservedConstrainedSpan(lm, generated);
      generated := enteredGenerated;
      insideConstrainedOut := enteredInside;
      currentConstrainedOut := enteredCurrent;
      openedByStrategy := false;
    } else {
      var openedGenerated, openedInside, openedCurrent := helpers.OpenConstrainedSpan(lm, generated);
      generated := openedGenerated;
      insideConstrainedOut := openedInside;
      currentConstrainedOut := openedCurrent;
      openedByStrategy := true;
      steps := steps + 1;
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    openedByStrategy := false;
    steps := steps + 1;
  } else if |currentConstrainedOut| >= rollbackLimit {
    var rolledGenerated, rolledCurrent := helpers.RollbackConstrainedSuffix(
      parser, generated, currentConstrainedOut
    );
    generated := rolledGenerated;
    insideConstrainedOut := true;
    currentConstrainedOut := rolledCurrent;
  } else {
    var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
    var constrainedPrompt := prompt + stablePrefix;
    var validCount := helpers.ValidTokenCount(parser, currentConstrainedOut);

    if stepTokenBudget > 1 && validCount > narrowThreshold {
      var remaining: nat := maxSteps - steps;
      var symbolBudget: nat := if stepTokenBudget > remaining then remaining else stepTokenBudget;
      var symbolGenerated, symbolOut, hitEos, stepsUsed := helpers.ConstrainedSymbolInGenerated(
        lm, parser, constrainedPrompt, generated, currentConstrainedOut, symbolBudget, eosToken
      );
      generated := symbolGenerated;
      currentConstrainedOut := symbolOut;
      steps := steps + stepsUsed;
      if hitEos {
        break;
      }
    } else {
      var next := eosToken;
      if validCount <= 2 {
        next := helpers.AdaptiveConstrainedStepWithPenalties(
          lm, parser, constrainedPrompt, currentConstrainedOut,
          validTokenGroups, 4.0, generated, 4.0, narrowThreshold, eosToken
        );
      } else if |currentConstrainedOut| == 0 {
        next := helpers.AdaptiveConstrainedStep(
          lm, parser, constrainedPrompt, currentConstrainedOut,
          validTokenGroups, 4.0, narrowThreshold, eosToken
        );
      } else if |currentConstrainedOut| <= 4 {
        var gatedNext, wasConstrained := helpers.ConfidenceGatedStep(
          lm, parser, constrainedPrompt, currentConstrainedOut, eosToken
        );
        next := gatedNext;
      } else {
        next := helpers.SafeRepetitionPenaltyStep(
          lm, parser, constrainedPrompt, currentConstrainedOut, generated, 2.0, eosToken
        );
      }

      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := appendedGenerated;
        insideConstrainedOut := appendedInside;
        currentConstrainedOut := appendedCurrent;
      }
    }
  }
}

cost := steps;

